#!/usr/bin/env python3
"""
Validate the processed HWPX file.
"""

import json
import zipfile
import re

def validate():
    print("=" * 60)
    print("VALIDATION REPORT")
    print("=" * 60)

    checks_passed = 0
    checks_failed = 0

    # 1. Check file exists and is valid ZIP
    try:
        with zipfile.ZipFile('/root/supplier_contact_ready.hwpx', 'r') as z:
            print("\n[✓] File exists and is a valid ZIP archive")
            checks_passed += 1

            file_list = z.namelist()
            print(f"    Files in archive: {file_list}")

            # Read all content for validation
            all_content = {}
            for f in file_list:
                all_content[f] = z.read(f).decode('utf-8')
    except Exception as e:
        print(f"\n[✗] File validation failed: {e}")
        checks_failed += 1
        return

    # 2. Check no {{ or }} remain in any file
    placeholder_pattern_found = False
    for fname, content in all_content.items():
        if '{{' in content or '}}' in content:
            print(f"\n[✗] Found placeholder pattern in {fname}")
            placeholder_pattern_found = True
            checks_failed += 1
    if not placeholder_pattern_found:
        print("\n[✓] No {{ or }} patterns remain in any file")
        checks_passed += 1

    # 3. Load JSON data for verification
    with open('/root/supplier_contact.json', 'r', encoding='utf-8') as f:
        json_data = json.load(f)

    # 4. Check all JSON values appear in XML content
    section_xml = all_content.get('Contents/section0.xml', '')
    missing_values = []
    for key, value in json_data.items():
        if value not in section_xml:
            missing_values.append((key, value))

    if missing_values:
        print(f"\n[✗] Some JSON values not found in XML:")
        for key, value in missing_values:
            print(f"    - {key}: {value}")
        checks_failed += 1
    else:
        print("\n[✓] All JSON values appear in XML content:")
        for key, value in json_data.items():
            print(f"    - {key}: {value}")
        checks_passed += 1

    # 5. Check Korean field labels are still present
    korean_labels = ['회사명:', '담당자:', '직책:', '대표전화:', '이메일:', '주소:', '계약 시작일:']
    missing_labels = [label for label in korean_labels if label not in section_xml]

    if missing_labels:
        print(f"\n[✗] Missing Korean field labels: {missing_labels}")
        checks_failed += 1
    else:
        print("\n[✓] All Korean field labels are present")
        for label in korean_labels:
            print(f"    - {label}")
        checks_passed += 1

    # 6. Check static note line is unchanged
    if '메모: 신규 공급사 등록용' in section_xml:
        print("\n[✓] Static note line is unchanged: '메모: 신규 공급사 등록용'")
        checks_passed += 1
    else:
        print("\n[✗] Static note line is missing or changed")
        checks_failed += 1

    # 7. Check modified paragraphs don't contain lineSegArray elements
    # Parse the XML to check for lineSegArray in modified paragraphs
    import xml.etree.ElementTree as ET
    root = ET.fromstring(section_xml)

    modified_paras_have_lineSegArray = False
    for para in root.iter():
        if para.tag.endswith('}p'):
            para_id = para.get('id', '')
            # Check if this is a data paragraph (id 1-7)
            if para_id in ['1', '2', '3', '4', '5', '6', '7']:
                for child in para:
                    if child.tag.endswith('}linesegarray'):
                        print(f"\n[✗] Paragraph {para_id} still contains lineSegArray")
                        modified_paras_have_lineSegArray = True
                        checks_failed += 1

    if not modified_paras_have_lineSegArray:
        print("\n[✓] Modified paragraphs (1-7) do not contain lineSegArray elements")
        checks_passed += 1

    # 8. Check title and memo paragraphs still exist and weren't modified
    title_found = False
    memo_found = False
    for para in root.iter():
        if para.tag.endswith('}p'):
            para_id = para.get('id', '')
            if para_id == '0':
                for elem in para.iter():
                    if elem.tag.endswith('}t') and elem.text == '거래처 연락처 카드':
                        title_found = True
            if para_id == '8':
                for elem in para.iter():
                    if elem.tag.endswith('}t') and elem.text == '메모: 신규 공급사 등록용':
                        memo_found = True

    if title_found:
        print("\n[✓] Title paragraph (id=0) is preserved")
        checks_passed += 1
    else:
        print("\n[✗] Title paragraph is missing or changed")
        checks_failed += 1

    if memo_found:
        print("\n[✓] Memo paragraph (id=8) is preserved")
        checks_passed += 1
    else:
        print("\n[✗] Memo paragraph is missing or changed")
        checks_failed += 1

    # Summary
    print("\n" + "=" * 60)
    print(f"SUMMARY: {checks_passed} checks passed, {checks_failed} checks failed")
    print("=" * 60)

    if checks_failed == 0:
        print("\n✓ All validation checks passed!")
        return True
    else:
        print(f"\n✗ {checks_failed} validation check(s) failed")
        return False

if __name__ == '__main__':
    success = validate()
    exit(0 if success else 1)
